"""docs/cheatsheet.html is generated by scripts/build_cheatsheet.py from real library runs; it must be current.

Regenerate with `python scripts/build_cheatsheet.py` after a change that alters any snippet's output.
"""
import subprocess
import sys
from html.parser import HTMLParser
from pathlib import Path

import pytest

pytestmark = pytest.mark.unit
ROOT = Path(__file__).resolve().parents[2]


def test_cheatsheet_is_up_to_date():
    r = subprocess.run([sys.executable, str(ROOT / "scripts" / "build_cheatsheet.py"), "--check"],
                       capture_output=True, text=True, cwd=ROOT, timeout=300)
    assert r.returncode == 0, r.stdout + r.stderr


def test_cheatsheet_html_is_well_formed():
    class Check(HTMLParser):
        VOID = {"meta", "br", "img", "hr", "link", "input"}

        def __init__(self):
            super().__init__()
            self.stack = []

        def handle_starttag(self, tag, attrs):
            if tag not in self.VOID:
                self.stack.append(tag)

        def handle_endtag(self, tag):
            assert self.stack and self.stack[-1] == tag, (tag, self.stack[-3:])
            self.stack.pop()

    c = Check()
    c.feed((ROOT / "docs" / "cheatsheet.html").read_text(encoding="utf-8"))
    assert c.stack == []
